/**
 * Generation III NPC trade encounters.
 *
 * Handheld trades use a fixed PID, IV spread, ability slot, trainer, nickname,
 * contest condition, and sheen. Their received level is the level of the
 * Pokémon offered by the player; each preset uses PKHeX's minimum legal level
 * and the initial moves generated by that title at that level.
 *
 * Pokémon XD trades are different: their IVs, ability slot, and PID come from
 * one CXD RNG sequence, so those fields remain finder-generated.
 */

import { LEARNSETS } from './learnsets.gen3.js';
import { LEARNSETS_FRLG } from './learnsets.frlg.js';

const EN = 2;
const LANGUAGES = Object.freeze([1, 2, 3, 4, 5, 7]);
const GAME_NAMES = Object.freeze({
  1: 'Sapphire',
  2: 'Ruby',
  3: 'Emerald',
  4: 'FireRed',
  5: 'LeafGreen',
  15: 'Pokémon XD',
});

function initialMoves(species, level, originGame) {
  const learnset = ([4, 5].includes(Number(originGame)) && LEARNSETS_FRLG[species])
    || LEARNSETS[species]?.l
    || [];
  return learnset
    .filter(([, learnedAt]) => Number(learnedAt) <= Number(level))
    .map(([move]) => Number(move))
    .slice(-4);
}

function contestStat(enhanced) {
  return Object.freeze({
    cool: enhanced === 'cool' ? 30 : 5,
    beauty: enhanced === 'beauty' ? 30 : 5,
    cute: enhanced === 'cute' ? 30 : 5,
    smart: enhanced === 'smart' ? 30 : 5,
    tough: enhanced === 'tough' ? 30 : 5,
    sheen: 10,
  });
}

function handheldTrade(definition, originGame, overrides = {}) {
  const gameName = GAME_NAMES[originGame];
  const entry = {
    ...definition,
    ...overrides,
    id: `${definition.id}_${gameName.toLowerCase()}`,
    label: `${gameName} — ${definition.nicknameByLanguage[EN]}`,
    tradeKind: 'handheld',
    pidType: 'FIXED',
    ivType: 'FIXED',
    originGame,
    location: 254,
    ball: 4,
    fateful: false,
    shinyLocked: true,
    nicknameLocked: true,
    allowedLanguages: LANGUAGES,
  };
  entry.fixedNature = entry.fixedPID % 25;
  entry.moves = initialMoves(entry.species, entry.level, originGame);
  return Object.freeze(entry);
}

